'use strict';
const fs=require('node:fs'),path=require('node:path');
const read=p=>fs.readFileSync(path.join(__dirname,p),'utf8');
let src='/* Alligator + Fractal — OneBullEx 1-minute port. MPL-2.0.\n'+
' * https://mozilla.org/MPL/2.0/ — Pine v5 strategy adaptation.\n'+
' * Default PAPER. Live requires user approval and user start.\n'+
' * Generated by examples/alligator-fractal/build.js. See README.md for differences.\n */\n'+
read('./execution.js')+'\n'+read('engine.js')+'\n'+read('runtime.js');
src=src.replace(/typeof createSpartansExecution!=='undefined'\?createSpartansExecution:require\('[^']+'\)\.createSpartansExecution/g,'createSpartansExecution')
 .replace(/typeof createAlligatorEngine!=='undefined'\?createAlligatorEngine:require\('[^']+'\)\.createAlligatorEngine/g,'createAlligatorEngine')
 .replace(/typeof alligatorDecision!=='undefined'\?alligatorDecision:require\('[^']+'\)\.alligatorDecision/g,'alligatorDecision')
 .replace(/^if\s*\(typeof module[^\n]+\)\s*(?:\n\s*)?module\.exports\s*=\s*[^;]+;\n?/gm,'');
if(/\brequire\s*\(|module\.exports/.test(src))throw Error('Node dependency in bundle');
fs.writeFileSync(path.join(__dirname,'Alligator-Fractal-OneBullEx.js'),src);
const parameters=[
 ['AF_RUN_MODE','執行模式：0=PAPER；1=LIVE',0,0,1],
 ['AF_SIZE_MODE','張數模式：0=權益百分比；1=固定張數測試',1,0,1],
 ['AF_FIXED_CONTRACTS','固定測試張數',1,1,100000],
 ['AF_EQUITY_PCT','原策略下單名目金額占權益百分比',10,0.01,100],
 ['AF_APPROVED_CAP','已核准且與bridge一致的單筆上限',1,1,100000],
 ['AF_MAX_ROUND_TRIPS','完成幾次開平倉後停止：0=持續運行',1,0,100000],
 ['AF_SHOW_LINES','繪製鱷魚與碎形',true],
 ['AF_ACCOUNT_LABEL','預期的FMZ交易所設定名稱','OneBullEx-Spartans']
].map(([name,label,value,min,max])=>({name,label,value,type:typeof value,...(min===undefined?{}:{min,max})}));
fs.writeFileSync(path.join(__dirname,'parameters.json'),JSON.stringify(parameters,null,2)+'\n');
console.log('Built '+src.length+' characters, '+parameters.length+' parameters');
